// Clock supplies the current time. It is injectable for deterministic tests.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// SystemClock returns a Clock backed by time.Now.
func SystemClock() Clock { return systemClock{} }

// Limiter is a concurrency-safe token bucket.
//
// Tokens are replenished continuously at rate tokens per second up to burst.
// Time never moves backward: a non-monotonic Clock is tolerated by ignoring
// negative elapsed durations.
type Limiter struct {
	mu sync.Mutex

	rate  float64
	burst float64
	clock Clock

	tokens float64
	last   time.Time
}

// New creates a token bucket with the given sustained rate (tokens/second)
// and maximum burst. The bucket starts full.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 || burst <= 0 {
		return nil, errors.New("ratelimit: rate and burst must be > 0")
	}
	if !isFinite(rate) {
		return nil, errors.New("ratelimit: rate must be finite")
	}
	if clock == nil {
		clock = SystemClock()
	}
	now := clock.Now()
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		clock:  clock,
		tokens: float64(burst),
		last:   now,
	}, nil
}

// MustNew is New but panics on invalid configuration.
func MustNew(rate float64, burst int, clock Clock) *Limiter {
	l, err := New(rate, burst, clock)
	if err != nil {
		panic(err)
	}
	return l
}

// Allow reports whether one token is available and consumes it if so.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available and consumes them if so.
//
// n <= 0 always succeeds without consuming tokens. n > burst always fails
// without consuming tokens. Calls are serialized by a mutex, so concurrent
// callers never oversubscribe the bucket.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}

	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	if elapsed := now.Sub(l.last).Seconds(); elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	} else if now.After(l.last) {
		// Sub overflowed or clock resolution collapsed; still advance last.
		l.last = now
	}

	need := float64(n)
	if need > l.burst || l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}

// Tokens returns the currently available tokens after refilling to now.
