// limiter.go
package tokenbucket

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock supplies the current time. It is injectable for deterministic tests.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
//
// Tokens are replenished continuously at rate tokens per second, up to capacity.
// AllowN consumes n tokens in a single atomic operation.
type Limiter struct {
	mu sync.Mutex

	clock    Clock
	rate     float64
	capacity float64

	tokens float64
	last   time.Time
}

// Config configures a Limiter.
type Config struct {
	// Rate is the number of tokens added per second. Must be > 0 and finite.
	Rate float64
	// Capacity is the maximum number of tokens. Must be > 0 and finite.
	Capacity float64
	// Clock is optional; time.Now is used when nil.
	Clock Clock
}

var (
	ErrInvalidRate     = errors.New("tokenbucket: rate must be > 0 and finite")
	ErrInvalidCapacity = errors.New("tokenbucket: capacity must be > 0 and finite")
	ErrInvalidN        = errors.New("tokenbucket: n must be > 0 and finite")
)

// New validates cfg and returns a Limiter initially full of tokens.
func New(cfg Config) (*Limiter, error) {
	if cfg.Rate <= 0 || isNonFinite(cfg.Rate) {
		return nil, ErrInvalidRate
	}
	if cfg.Capacity <= 0 || isNonFinite(cfg.Capacity) {
		return nil, ErrInvalidCapacity
	}
	if cfg.Clock == nil {
		cfg.Clock = systemClock{}
	}

	now := cfg.Clock.Now()
	return &Limiter{
		clock:    cfg.Clock,
		rate:     cfg.Rate,
		capacity: cfg.Capacity,
		tokens:   cfg.Capacity,
		last:     now,
	}, nil
}

// MustNew is New but panics on invalid configuration.
func MustNew(cfg Config) *Limiter {
	l, err := New(cfg)
	if err != nil {
		panic(fmt.Sprintf("tokenbucket: invalid config: %v", err))
	}
	return l
}

// Allow reports whether one token is available and consumes it if so.
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN reports whether n tokens are available and consumes them if so.
// n must be > 0 and finite. Requests larger than capacity never succeed.
func (l *Limiter) AllowN(n float64) bool {
	if n <= 0 || isNonFinite(n) {
		return false
	}

	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	l.refill(now)

	if n > l.capacity || l.tokens < n {
		return false
	}
	l.tokens -= n
	return true
}

// Tokens returns the currently available token count after refilling.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}

// refill must be called with l.mu held.
func (l *Limiter) refill(now time.Time) {
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = min(l.capacity, l.tokens+l.rate*elapsed)
		l.last = now
		return
	}

	// Handle non-monotonic clocks by not moving backwards. If the clock jumps
	// backwards significantly, re-anchor to avoid a long stalled refill window.
	if now.Before(l.last) {
		if l.last.Sub(now) > time.Second {
			l.last = now
		}
	}
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}

func isNonFinite(v float64) bool {
	return v != v || v > 1.7976931348623157e308 || v < -1.7976931348623157e308
}
