func TestConcurrentAllowN(t *testing.T) {
	fc := newFakeClock(time.Unix(0, 0).UTC())
	const capacity = 100
	l := MustNew(Config{Rate: 0, Capacity: capacity, Clock: fc})

	// Rate is validated as > 0; use a tiny rate and no time advancement instead.
	l = MustNew(Config{Rate: 1e-12, Capacity: capacity, Clock: fc})

	const goroutines = 200
	var wg sync.WaitGroup
	var mu sync.Mutex
	allowed := 0

	wg.Add(goroutines)
	for i := 0; i < goroutines; i++ {
		go func() {
			defer wg.Done()
			if l.AllowN(1) {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()

	if allowed != capacity {
		t.Fatalf("allowed = %d, want %d", allowed, capacity)
	}
	if got := l.Tokens(); !almostEqual(got, 0) {
		t.Fatalf("tokens = %v, want 0", got)
	}
}

func almostEqual(a, b float64) bool {
	return math.Abs(a-b) <= 1e-9
